        header[CHKSUM_OFFSET + 2] = '3';
        header[CHKSUM_OFFSET + 3] = '4';
        header[CHKSUM_OFFSET + 4] = '5';
        header[CHKSUM_OFFSET + 5] = '6';
        header[CHKSUM_OFFSET + 6] = '7';

        // digits should stop at 6. storedSum = 123456 (octal)
        // unsignedSum = 200 * 32 = 6400
        // 123456 (octal) is 42862 (dec).
        // 42862 > 6400 is true.
        assertTrue(TarUtils.verifyCheckSum(header));
    }

    @Test
    public void testVerifyCheckSum_InvalidOctalDigit() {
        // Test the 'else if (digits > 0) digits = 6' branch
        byte[] header = createBaseHeader(200);
        header[CHKSUM_OFFSET] = '1';
        header[CHKSUM_OFFSET + 1] = '2';
        header[CHKSUM_OFFSET + 2] = '8'; // Not an octal digit

        // digits was 2. Now it hits 'else if (digits > 0)', digits becomes 6.
        // storedSum = 1*8 + 2 = 10.
        // unsignedSum = 6400.
        // 10 == 6400 (F) || 10 > 6400 (F) -> false.
        assertFalse(TarUtils.verifyCheckSum(header));
