        // Test signedSum vs unsignedSum
        // If we have a byte 0xFF (-1)
        // unsignedSum adds 255, signedSum adds -1.
        byte[] header = new byte[200];
        for(int i=0; i<200; i++) header[i] = 0; // all zeros
