public class ArrayUtils_lastIndexOf_TriageGen2Test {

    private static final int INDEX_NOT_FOUND = -1;

    @Test
    public void testLastIndexOf_NullArray() {
        assertEquals(INDEX_NOT_FOUND, ArrayUtils.lastIndexOf(null, true, 0));
    }

    @Test
    public void testLastIndexOf_EmptyArray() {
        assertEquals(INDEX_NOT_FOUND, ArrayUtils.lastIndexOf(new boolean[]{}, true, 0));
    }

    @Test
    public void testLastIndexOf_StartIndexNegative() {
        boolean[] array = {true, false, true};
        assertEquals(INDEX_NOT_FOUND, ArrayUtils.lastIndexOf(array, true, -1));
    }

    @Test
    public void testLastIndexOf_StartIndexOutOfBoundsHigh() {
        boolean[] array = {true, false, true};
        // startIndex >= array.length, should clamp to array.length - 1
        // array.length - 1 is 2. array[2] is true.
        assertEquals(2, ArrayUtils.lastIndexOf(array, true, 10));
    }

    @Test
    public void testLastIndexOf_FoundAtStartIndex() {
        boolean[] array = {true, false, false, true, false};
        assertEquals(3, ArrayUtils.lastIndexOf(array, true, 3));
    }

    @Test
    public void testLastIndexOf_FoundBeforeStartIndex() {
        boolean[] array = {true, false, true, false, false};
        // Search from index 2 (true) backwards. Last true is at index 2.
        assertEquals(2, ArrayUtils.lastIndexOf(array, true, 2));
        // Search from index 4 (false) backwards. Last true is at index 2.
        assertEquals(2, ArrayUtils.lastIndexOf(array, true, 4));
    }

    @Test
    public void testLastIndexOf_ValueNotFound() {
        boolean[] array = {true, true, false, false};
        assertEquals(INDEX_NOT_FOUND, ArrayUtils.lastIndexOf(array, true, 1)); // Only looks at index 1 and 0
        assertEquals(INDEX_NOT_FOUND, ArrayUtils.lastIndexOf(array, false, 0)); // Only looks at index 0
        assertEquals(INDEX_NOT_FOUND, ArrayUtils.lastIndexOf(array, true, 0)); // false is not in array if searching for true at 0? No, true is at 0.

        // Correct logic for Not Found:
        boolean[] array2 = {true, true, false};
        assertEquals(INDEX_NOT_FOUND, ArrayUtils.lastIndexOf(array2, false, 0)); 
    }

    @Test
    public void testLastIndexOf_FoundAtZero() {
        boolean[] array = {true, false, false};
        assertEquals(0, ArrayUtils.lastIndexOf(array, true, 0));
    }

    @Test
    public void testLastIndexOf_MultipleOccurrences() {
        boolean[] array = {true, false, true, true, false};
        // Last index of true starting from index 4 is 3
        assertEquals(3, ArrayUtils.lastIndexOf(array, true, 4));
        // Last index of false starting from index 2 is 1
        assertEquals(1, ArrayUtils.lastIndexOf(array, false, 2));
