package org.apache.commons.math.util;

import static org.junit.Assert.assertEquals;
import org.junit.Test;

/**
 * Unit tests for MathUtils.normalizeAngle.
 * The method normalizes an angle 'a' to be within the range [center - PI, center + PI).
 */
public class MathUtils_normalizeAngle_TriageGen1Test {

    private static final double DELTA = 1e-12;
    private static final double TWO_PI = 2.0 * Math.PI;

    @Test
    public void testNormalizeAngle_AlreadyNormalized() {
        double center = 0.0;
        double a = 1.0;
        // 1.0 is within [-PI, PI)
        assertEquals(a, MathUtils.normalizeAngle(a, center), DELTA);
    }

    @Test
    public void testNormalizeAngle_CenterZero() {
        double center = 0.0;

        // Test positive overflow
        assertEquals(Math.PI - 0.1, MathUtils.normalizeAngle(2.0 * Math.PI + (Math.PI - 0.1), center), DELTA);

        // Test negative overflow
        assertEquals(-Math.PI + 0.1, MathUtils.normalizeAngle(-2.0 * Math.PI + (-Math.PI + 0.1), center), DELTA);

        // Test exact boundary (should wrap to -PI)
        // The formula: a - 2PI * floor((a + PI - 0)/2PI)
        // If a = PI: PI - 2PI * floor(2PI/2PI) = PI - 2PI = -PI
        assertEquals(-Math.PI, MathUtils.normalizeAngle(Math.PI, center), DELTA);
    }

    @Test
    public void testNormalizeAngle_NonZeroCenter() {
        double center = Math.PI; // Range should be [0, 2PI)

        // a = 0.5 * PI -> should stay 0.5 * PI
        assertEquals(0.5 * Math.PI, MathUtils.normalizeAngle(0.5 * Math.PI, center), DELTA);

        // a = 2.5 * PI -> maps to 0.5 * PI
        assertEquals(0.5 * Math.PI, MathUtils.normalizeAngle(2.5 * Math.PI, center), DELTA);

        // a = -0.5 * PI -> maps to 1.5 * PI
        // floor((-0.5PI + PI - PI)/2PI) = floor(-0.5PI/2PI) = -1
        // -0.5PI - 2PI*(-1) = 1.5PI
        assertEquals(1.5 * Math.PI, MathUtils.normalizeAngle(-0.5 * Math.PI, center), DELTA);
    }

    @Test
    public void testNormalizeAngle_LargeValues() {
        double center = 0.0;
        double a = 100.0 * TWO_PI + 0.5;
        assertEquals(0.5, MathUtils.normalizeAngle(a, center), DELTA);

        double aNeg = -100.0 * TWO_PI - 0.5;
        // -0.5 normalized to [-PI, PI) is -0.5
        assertEquals(-0.5, MathUtils.normalizeAngle(aNeg, center), DELTA);
    }

    @Test
    public void testNormalizeAngle_ExactMultiples() {
        double center = 0.0;
        // Test exact 2PI
        // floor((2PI + PI)/2PI) = floor(1.5) = 1
        // 2PI - 2PI(1) = 0
        assertEquals(0.0, MathUtils.normalizeAngle(TWO_PI, center), DELTA);

        // Test exact -2PI
        // floor((-2PI + PI)/2PI) = floor(-0.5) = -1
        // -2PI - 2PI(-1) = 0
        assertEquals(0.0, MathUtils.normalizeAngle(-TWO_PI, center), DELTA);
    }
}
