        // Data with 4 observations and 2 variables
        // x = [1, 2, 3, 4], y = [2, 4, 6, 8] -> perfect correlation r = 1.0
        // nObs = 4
        // Standard error formula: sqrt((1 - r^2) / (nObs - 2))
        // For r = 1: sqrt((1 - 1)/2) = 0
        // For r = 0: sqrt((1 - 0)/2) = sqrt(0.5) = 0.70710678118

        double[][] data = {
            {1.0, 2.0},
            {2.0, 4.0},
            {3.0, 6.0},
            {4.0, 8.0}
