        int nVars = 2;
        Assert.assertEquals(nVars, seMatrix.getRowDimension());
        Assert.assertEquals(nVars, seMatrix.getColumnDimension());

        // Diagonal elements (r=1) should be 0
        Assert.assertEquals(0.0, seMatrix.getEntry(0, 0), EPSILON);
        Assert.assertEquals(0.0, seMatrix.getEntry(1, 1), EPSILON);

        // Off-diagonal elements (r=1) should be 0
